mapper.select:
SELECT 
FROM ai_inspect_event
WHERE deleted = 0 AND handled = 1

    AND template_id = #{templateId}
    AND fp_id = #{fpId}

ORDER BY handle_time DESC, id DESC LIMIT 1

mapper.update:
UPDATE ai_inspect_event
SET total_count    = #{totalCount},
    last_seen_time = #{lastSeenTime}

        , severity = #{severity}


        , trigger_reason = #{triggerReason}



        , app_count = GREATEST(app_count, #{appCount})


        , app_list = #{appList}


        , frame_list = #{frameList}

WHERE id = #{id}

UPDATE ai_inspect_event
SET handled = 1, handle_note = #{note}, handler = #{handler}, handle_time = NOW()
WHERE id = #{id}

UPDATE ai_inspect_event
SET push_count = push_count + 1,
    last_push_time = #{pushTime}
WHERE id = #{id}

UPDATE ai_inspect_event
SET push_count = push_count + 1,
    last_push_time = #{pushTime},
    last_message_id = #{messageId}
WHERE id = #{id}

mapper.select:
SELECT FROM ai_inspect_event e WHERE e.deleted = 0 AND e.handled = 0 AND e.fp_id IS NOT NULL AND (e.last_analyze_time IS NULL OR (e.last_analyze_time < #{before}
AND (e.analyzed_total IS NULL OR e.total_count >= e.analyzed_total * #{growth} OR e.app_count > COALESCE(e.analyzed_app_count, 0))))
AND e.event_type <> 'SURGE'
AND (e.event_type = 'SURGE' OR NOT EXISTS ( SELECT 1 FROM ai_inspect_library l WHERE l.id = e.template_id AND l.deleted = 0 AND l.business_expected = 1 )) ORDER BY e.last_analyze_time IS NOT NULL, e.total_count DESC LIMIT #{limit}

mapper.update:
UPDATE ai_inspect_event
SET analyzed_total = #{total}, analyzed_app_count = #{appCount}
WHERE id = #{id}

mapper.sql:
WHERE deleted = 0

    AND handled = #{handled}


    AND event_type = #{eventType}


    AND app_id = #{appId}


    AND severity = #{severity}


    AND first_seen_time >= #{since}


    AND (headline LIKE CONCAT('%', #{keyword}, '%')
         OR exc_simple LIKE CONCAT('%', #{keyword}, '%')
         OR exc_cause LIKE CONCAT('%', #{keyword}, '%')
         OR app_id LIKE CONCAT('%', #{keyword}, '%'))

WHERE e.deleted = 0

    AND e.handled = #{handled}


    AND e.event_type = #{eventType}


    AND e.app_id = #{appId}


    AND e.severity = #{severity}


    AND e.first_seen_time >= #{since}


    AND (e.headline LIKE CONCAT('%', #{keyword}, '%')
         OR e.exc_simple LIKE CONCAT('%', #{keyword}, '%')
         OR e.exc_cause LIKE CONCAT('%', #{keyword}, '%')
         OR e.app_id LIKE CONCAT('%', #{keyword}, '%'))

mapper.update:
UPDATE ai_inspect_event
SET severity = #{severity}
WHERE id = #{id} AND deleted = 0
